import { loadRecord, LoadError } from './loader';
import { TransformResult } from './types';

describe('loader', () => {
  const sampleRecord: TransformResult = {
    id: 100,
    slug: 'sample-record',
    sourceUrl: 'https://api.example.com/items/100',
    transformedAt: new Date().toISOString(),
  };

  it('successfully loads record into database table', async () => {
    const result = await loadRecord('analytics_events', sampleRecord);

    expect(result).toBeDefined();
    expect(result.success).toBe(true);
    expect(result.insertedId).toBe(100);
    expect(result.table).toBe('analytics_events');
  });

  it('fails with LoadError on duplicate key violation', async () => {
    const duplicateRecord: TransformResult = {
      ...sampleRecord,
      id: -1,
    };

    try {
      await loadRecord('analytics_events', duplicateRecord);
      expect.fail('Should have thrown LoadError');
    } catch (err) {
      expect(err).toBeInstanceOf(LoadError);
      const loadErr = err as LoadError;
      expect(loadErr.table).toBe('analytics_events');
      expect(loadErr.tableName).toBe('analytics_events');
      expect(loadErr.operation).toBe('insert');
      expect(loadErr.message).toContain('Duplicate key violation');
      expect(loadErr.message).toContain('-1');
    }
  });

  it('fails with LoadError on database connection error', async () => {
    try {
      await loadRecord('connection_error_table', sampleRecord);
      expect.fail('Should have thrown LoadError');
    } catch (err) {
      expect(err).toBeInstanceOf(LoadError);
      const loadErr = err as LoadError;
      expect(loadErr.table).toBe('connection_error_table');
      expect(loadErr.operation).toBeDefined();
      expect(loadErr.message).toMatch(/connection error/i);
    }

    // Also verify via simulateConnectionError option
    try {
      await loadRecord('users', sampleRecord, { simulateConnectionError: true });
      expect.fail('Should have thrown LoadError');
    } catch (err) {
      expect(err).toBeInstanceOf(LoadError);
      const loadErr = err as LoadError;
      expect(loadErr.table).toBe('users');
      expect(loadErr.message).toMatch(/connection error/i);
    }
  });

  it('fails with LoadError on missing table name', async () => {
    try {
      await loadRecord('', sampleRecord);
      expect.fail('Should have thrown LoadError');
    } catch (err) {
      expect(err).toBeInstanceOf(LoadError);
      const loadErr = err as LoadError;
      expect(loadErr.message).toContain('Missing destination table name');
    }
  });
});

import { describe, it, expect, vi } from 'vitest';
import { runPipeline } from './pipeline';
import { PipelineError, PipelineStageError } from './types';

describe('Data Pipeline', () => {
  it('successfully processes full pipeline (fetch -> transform -> load)', async () => {
    const result = await runPipeline({
      url: 'https://api.example.com/items',
      tableName: 'items_table',
    });

    expect(result).toBeDefined();
    expect(result.fetch.status).toBe(200);
    expect(result.fetch.url).toBe('https://api.example.com/items');

    expect(result.transform.slug).toBe('sample-payload');
    expect(result.transform.sourceUrl).toBe('https://api.example.com/items');
    expect(result.transform.id).toBe(1);

    expect(result.load.success).toBe(true);
    expect(result.load.insertedId).toBe(1);
    expect(result.load.table).toBe('items_table');
  });

  it('fails with PipelineError at fetch stage on invalid URL', async () => {
    await expect(
      runPipeline({
        url: 'invalid-url',
        tableName: 'items_table',
      })
    ).rejects.toThrow(PipelineError);

    try {
      await runPipeline({
        url: 'invalid-url',
        tableName: 'items_table',
      });
      expect.fail('Should have thrown');
    } catch (err) {
      expect(err).toBeInstanceOf(PipelineError);
      expect(err).toBeInstanceOf(PipelineStageError);
      const pipelineErr = err as PipelineStageError;
      expect(pipelineErr.stage).toBe('fetch');
      expect(pipelineErr.message).toContain('Fetch stage failed');
      expect(pipelineErr.cause).toBeDefined();
    }
  });

  it('fails with PipelineError at fetch stage on 500 error URL', async () => {
    try {
      await runPipeline({
        url: 'https://api.example.com/error',
        tableName: 'items_table',
      });
      expect.fail('Should have thrown');
    } catch (err) {
      expect(err).toBeInstanceOf(PipelineError);
      const pipelineErr = err as PipelineError;
      expect(pipelineErr.stage).toBe('fetch');
      expect(pipelineErr.message).toContain('Fetch stage failed');
    }
  });

  it('fails with PipelineError at transform stage if data transformation fails', async () => {
    const transformer = await import('./transformer');
    const spy = vi.spyOn(transformer, 'transformData').mockRejectedValueOnce(new Error('Invalid payload structure'));

    try {
      await runPipeline({
        url: 'https://api.example.com/items',
        tableName: 'items_table',
      });
      expect.fail('Should have thrown');
    } catch (err) {
      expect(err).toBeInstanceOf(PipelineError);
      expect(err).toBeInstanceOf(PipelineStageError);
      const pipelineErr = err as PipelineStageError;
      expect(pipelineErr.stage).toBe('transform');
      expect(pipelineErr.message).toContain('Transform stage failed');
      expect(pipelineErr.cause).toBeDefined();
    } finally {
      spy.mockRestore();
    }
  });

  it('fails with PipelineError at load stage on missing table name', async () => {
    try {
      await runPipeline({
        url: 'https://api.example.com/items',
        tableName: '',
      });
      expect.fail('Should have thrown');
    } catch (err) {
