import { describe, it, expect, vi } from 'vitest';
import { runPipeline, pipeline } from './pipeline';
import { PipelineError, PipelineStageError } from './types';

describe('Data Pipeline', () => {
  it('successfully processes full pipeline (fetch -> transform -> load)', async () => {
    const result = await runPipeline({
      url: 'https://api.example.com/items',
      tableName: 'items_table',
    });

    expect(result).toBeDefined();
    expect(result.fetch.status).toBe(200);
    expect(result.fetch.url).toBe('https://api.example.com/items');

    expect(result.transform.slug).toBe('sample-payload');
    expect(result.transform.sourceUrl).toBe('https://api.example.com/items');
    expect(result.transform.id).toBe(1);

    expect(result.load.success).toBe(true);
    expect(result.load.insertedId).toBe(1);
    expect(result.load.table).toBe('items_table');
  });

  it('fails with PipelineError at fetch stage on invalid URL', async () => {
    await expect(
      runPipeline({
        url: 'invalid-url',
        tableName: 'items_table',
      })
    ).rejects.toThrow(PipelineError);

    try {
      await runPipeline({
        url: 'invalid-url',
        tableName: 'items_table',
      });
      expect.fail('Should have thrown');
    } catch (err) {
      expect(err).toBeInstanceOf(PipelineError);
      expect(err).toBeInstanceOf(PipelineStageError);
      const pipelineErr = err as PipelineStageError;
      expect(pipelineErr.stage).toBe('fetch');
      expect(pipelineErr.message).toContain('Fetch stage failed');
      expect(pipelineErr.cause).toBeDefined();
    }
  });

  it('fails with PipelineError at fetch stage on 500 error URL', async () => {
    try {
      await runPipeline({
        url: 'https://api.example.com/error',
        tableName: 'items_table',
      });
      expect.fail('Should have thrown');
    } catch (err) {
      expect(err).toBeInstanceOf(PipelineError);
      const pipelineErr = err as PipelineError;
      expect(pipelineErr.stage).toBe('fetch');
      expect(pipelineErr.message).toContain('Fetch stage failed');
    }
  });

  it('fails with PipelineError at transform stage if data transformation fails', async () => {
    const transformer = await import('./transformer');
    const spy = vi.spyOn(transformer, 'transformData').mockRejectedValueOnce(new Error('Invalid payload structure'));

    try {
      await runPipeline({
        url: 'https://api.example.com/items',
        tableName: 'items_table',
      });
      expect.fail('Should have thrown');
    } catch (err) {
      expect(err).toBeInstanceOf(PipelineError);
      expect(err).toBeInstanceOf(PipelineStageError);
      const pipelineErr = err as PipelineStageError;
      expect(pipelineErr.stage).toBe('transform');
      expect(pipelineErr.message).toContain('Transform stage failed');
      expect(pipelineErr.cause).toBeDefined();
    } finally {
      spy.mockRestore();
    }
  });

  it('fails with PipelineError at load stage on missing table name', async () => {
    try {
      await runPipeline({
        url: 'https://api.example.com/items',
        tableName: '',
      });
      expect.fail('Should have thrown');
    } catch (err) {
      expect(err).toBeInstanceOf(PipelineError);
      expect(err).toBeInstanceOf(PipelineStageError);
      const pipelineErr = err as PipelineStageError;
      expect(pipelineErr.stage).toBe('load');
      expect(pipelineErr.message).toContain('Load stage failed');
    }
  });

  describe('Concurrent Pipeline (pipeline.run)', () => {
    it('processes 3 URLs with 2 concurrency', async () => {
      let active = 0;
      let maxActive = 0;

      const fetcher = await import('./fetcher');
      const originalFetchUrl = fetcher.fetchUrl;
      const fetchSpy = vi.spyOn(fetcher, 'fetchUrl').mockImplementation(async (...args) => {
        active++;
        maxActive = Math.max(maxActive, active);
        try {
          return await originalFetchUrl(...args);
        } finally {
          active--;
        }
      });

      try {
        const urls = [
          'https://api.example.com/item/1',
          'https://api.example.com/item/2',
          'https://api.example.com/item/3',
        ];

        const results = await pipeline.run({
          urls,
          tableName: 'concurrent_table',
          concurrency: 2,
        });

        expect(results).toHaveLength(3);
        expect(results[0].status).toBe('fulfilled');
        expect(results[1].status).toBe('fulfilled');
        expect(results[2].status).toBe('fulfilled');

        expect(maxActive).toBeLessThanOrEqual(2);
      } finally {
        fetchSpy.mockRestore();
      }
    });

    it('ensures that one failure does not stop others from completing', async () => {
      const urls = [
        'https://api.example.com/item/1',
        'https://api.example.com/error',
        'https://api.example.com/item/3',
      ];

      const results = await pipeline.run({
        urls,
        tableName: 'items_table',
        concurrency: 2,
      });

      expect(results).toHaveLength(3);

      expect(results[0].status).toBe('fulfilled');
      if (results[0].status === 'fulfilled') {
        expect(results[0].value.fetch.url).toBe('https://api.example.com/item/1');
        expect(results[0].value.load.success).toBe(true);
      }

      expect(results[1].status).toBe('rejected');
      if (results[1].status === 'rejected') {
